(async()=>{try{const api=await import('./feud-sequence.js?v=motion-v83');if(!window.motionTrialReady)await new Promise(r=>window.addEventListener('motion-trial-ready',r,{once:true}));for(const[k,v]of Object.entries(api.feudDefaults))if(fx[k]===undefined)fx[k]=structuredClone(v);const oldPhases=phaseTimes,oldFrame=frame,oldControls=renderDepotControls,seconds=t*settings.duration,start=()=>oldPhases().end;for(const[k,file]of Object.entries(api.feudSources)){sources[k]='assets/'+file;if(!sprites[k]){const im=new Image();im.onload=()=>{base._renderKey='';};im.src=sources[k];sprites[k]=im;}}restoreAssets();globalThis.motionTagSources?.();phaseTimes=()=>{const p=oldPhases();return{...p,end:p.end+(fx.feudEnabled?api.feudDuration(fx):0)}};
frame=function(el,p){const duration=settings.duration,time=p*duration,prior=phaseTimes;try{phaseTimes=oldPhases;settings.duration=oldPhases().end;oldFrame(el,Math.min(time,settings.duration-.000001)/settings.duration);}finally{phaseTimes=prior;settings.duration=duration;}let canvas=el.querySelector('.documentaryFeud');if(!fx.feudEnabled||time<start()){if(canvas)canvas.style.display='none';return;}if(!canvas){canvas=document.createElement('canvas');canvas.width=960;canvas.height=540;canvas.className='tearCanvas documentaryFeud';canvas.style.cssText='position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:52';el.append(canvas);}canvas.style.display='block';for(const slot of Object.keys(api.feudSources)){const media=sprites[fx.feudSourceBindings[slot]||slot];if(media?.tagName==='VIDEO'&&media.readyState>=2){const target=Math.max(0,api.feudState(time-start(),fx).source-655)%Math.max(.01,media.duration);if(Math.abs(media.currentTime-target)>.08)media.currentTime=target;}}api.paintFeud(canvas.getContext('2d'),Math.min(time-start(),api.feudDuration(fx)),sprites,fx);};
function refresh(){api.validateFeud(fx);const sec=t*settings.duration;syncDuration();t=Math.min(1,sec/settings.duration);saveEffects();base._renderKey='';frame(base,t);}function seek(source){openEditor();playing=false;t=(start()+api.feudSourceToLocal(source,fx))/settings.duration;frame(base,t);const scrub=document.querySelector('#scrub');if(scrub)scrub.value=t*1000;}
renderDepotControls=function(){oldControls();const host=document.querySelector('#depotControls');if(!host)return;const box=document.createElement('details');box.className='directorSection';box.innerHTML='<summary>Courtroom → feud → Chapter 4 ·10:55–11:55</summary>';host.prepend(box);const previews=document.createElement('div');previews.className='directorGrid';for(const s of api.feudStages){const b=document.createElement('button');b.className='pill';b.textContent=s.label;b.onclick=()=>seek((s.from+s.to)/2);previews.append(b);}box.append(previews);
const json=document.createElement('textarea');json.value=JSON.stringify(Object.fromEntries(Object.keys(api.feudDefaults).map(k=>[k,fx[k]])),null,2);json.setAttribute('aria-label','Feud scene settings');const apply=document.createElement('button');apply.className='pill';apply.textContent='Apply scene settings';apply.onclick=()=>{try{const v=JSON.parse(json.value);api.validateFeud(v);for(const k of Object.keys(api.feudDefaults))if(v[k]!==undefined)fx[k]=structuredClone(v[k]);refresh();renderDepotControls();}catch(e){apply.textContent=e.message;}};box.append(json,apply);
const select=document.createElement('select');for(const l of api.feudLayerCatalog)select.add(new Option(l.label,l.id));const edits=document.createElement('textarea'),update=document.createElement('button');update.className='pill';update.textContent='Apply selected object motion';function read(){edits.value=JSON.stringify(fx.feudLayerEdits[select.value]||{visible:true,x:0,y:0,scale:1,rotation:0,opacity:1,blur:0,depth:2,motion:{}},null,2);}select.onchange=read;read();update.onclick=()=>{try{const v=JSON.parse(edits.value),next={...fx.feudLayerEdits,[select.value]:v};api.validateFeud({...fx,feudLayerEdits:next});fx.feudLayerEdits=next;refresh();}catch(e){update.textContent=e.message;}};box.append(select,edits,update);
const replace=document.createElement('button');replace.className='pill';replace.textContent='Replace selected picture/video';replace.onclick=()=>{const slot=api.feudLayerCatalog.find(l=>l.id===select.value)?.slot;if(!slot)return;const picker=document.createElement('input');picker.type='file';picker.accept='image/*,video/*';picker.onchange=async()=>{const file=picker.files[0];if(!file)return;const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});const prior=sprites[slot]?.src;if(prior&&prior!==sources[slot]){const key=slot+'-archive-'+Date.now();await saveAsset(key,prior);(fx.feudReplacementHistory??=[]).push({slot,key});}if(file.type.startsWith('video/')){const v=document.createElement('video');v.muted=true;v.playsInline=true;v.preload='auto';v.src=data;v.onloadeddata=refresh;v.onseeked=()=>frame(base,t);sprites[slot]=v;}else{const im=new Image();im.onload=refresh;im.src=data;sprites[slot]=im;}fx.feudSourceBindings[slot]=slot;await saveAsset(slot,data);refresh();};picker.click();};box.append(replace);const note=document.createElement('p');note.className='sub';note.textContent='Fictional reconstruction. Independent collage, masks, multi-view heads, factory split, fire and chapter letters. Head views blend; no recovered 3D acting.';box.append(note);};renderDepotControls();syncDuration();t=Math.min(1,seconds/settings.duration);saveEffects();window.MotionFeud={...api,start,seek};registerCapability('doc-feud',{label:'Feud, factory split and Chapter 4',category:'Documentary actions',defaults:api.feudDefaults,slots:Object.keys(api.feudSources),render:(c,age,layer)=>api.paintFeud(c,age,sprites,{...fx,...layer.params})});window.motionFeudReady=true;window.dispatchEvent(new Event('motion-feud-ready'));}catch(e){console.error('Feud continuation',e);}})();
